function getTrigramScore(c1, c2, c3) {
    const key = (c1 << 16) | c2;
    let left = 0, right = _TRI_PACKED.length - 1;
    while (left <= right) {
        const mid = (left + right) >>> 1;
        const midVal = _TRI_PACKED[mid];
        if (midVal < key) left = mid + 1;
        else if (midVal > key) right = mid - 1;
        else {
            const start = _TRI_OFFSETS[mid];
            const end = _TRI_OFFSETS[mid + 1];
            for (let i = start; i < end; i++) {
                if (_TRI_C[i] === c3) {
                    return 1 - (i - start) / (end - start);
                }
            }
            return null;
        }
    }
    return null;
}

function getModelScore(char, prevChar, prevPrevChar) {
    if (typeof compress !== 'function') return 0;
    const c2 = compress(prevChar);
    const c3 = compress(char);
    if (c2 === undefined || c3 === undefined) return 0;
    if (prevPrevChar !== undefined) {
        const c1 = compress(prevPrevChar);
        if (c1 !== undefined) {
            const s = getTrigramScore(c1, c2, c3);
            if (s !== null) return s;
        }
    }
    return getBigramScore(c2, c3);
}

